Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
iavf: fix PTP use-after-free during reset

Commit 7c01dbfc8a1c5f ("iavf: periodically cache PHC time") introduced a
worker to cache PHC time, but failed to stop it during reset or disable.

This creates a race condition where `iavf_reset_task()` or
`iavf_disable_vf()` free adapter resources (AQ) while the worker is still
running. If the worker triggers `iavf_queue_ptp_cmd()` during teardown, it
accesses freed memory/locks, leading to a crash.

Fix this by calling `iavf_ptp_release()` before tearing down the adapter.
This ensures `ptp_clock_unregister()` synchronously cancels the worker and
cleans up the chardev before the backing resources are destroyed.

Fixes: 7c01dbfc8a1c5f ("iavf: periodically cache PHC time")
Signed-off-by: Petr Oros <poros@redhat.com>
Reviewed-by: Ivan Vecera <ivecera@redhat.com>
Acked-by: Jacob Keller <jacob.e.keller@intel.com>
Reviewed-by: Vadim Fedorenko <vadim.fedorenko@linux.dev>
Reviewed-by: Paul Menzel <pmenzel@molgen.mpg.de>
Reviewed-by: Aleksandr Loktionov <aleksandr.loktionov@intel.com>
Signed-off-by: Tony Nguyen <anthony.l.nguyen@intel.com>

Here is the root cause:
The PTP periodic worker introduced in commit 7c01dbfc8a1c5f was not stopped during adapter reset or disable, creating a race condition where the worker accesses freed resources (e.g., admin queue) after teardown, leading to use-after-free.

Here is the patch:
  */
 static void iavf_disable_vf(struct iavf_adapter *adapter)
 {
 	struct iavf_mac_filter *f, *ftmp;
 	struct iavf_vlan_filter *fv, *fvtmp;
 	struct iavf_cloud_filter *cf, *cftmp;

 	netdev_assert_locked(adapter->netdev);

 	adapter->flags |= IAVF_FLAG_PF_COMMS_FAILED;

+	iavf_ptp_release(adapter);
+
 	/* We don't use netif_running() because it may be true prior to
 	 * ndo_open() returning, so we can't assume it means all our open
 	 * tasks have finished, since we're not holding the rtnl_lock here.
 	 */
 	if (adapter->state == __IAVF_RUNNING) {
 		set_bit(__IAVF_VSI_DOWN, adapter->vsi.state);
 		netif_carrier_off(adapter->netdev);
 		netif_tx_disable(adapter->netdev);
 		adapter->link_up = false;
 		iavf_napi_disable_all(adapter);
 		iavf_irq_disable(adapter);
 		iavf_free_traffic_irqs(adapter);
 		iavf_free_all_tx_resources(adapter);
 		iavf_free_all_rx_resources(adapter);
 	}

 	spin_lock_bh(&adapter->mac_vlan_list_lock);

 	/* Delete all of the filters */
 	list_for_each_entry_safe(f, ftmp, &adapter->mac_filter_list, list) {
 		list_del(&f->list);
 		kfree(f);
 	}

 	list_for_each_entry_safe(fv, fvtmp, &adapter->vlan_filter_list, list) {
 		list_del(&fv->list);
 		kfree(fv);
 	}
 	adapter->num_vlan_filters = 0;

 	spin_unlock_bh(&adapter->mac_vlan_list_lock);

 	spin_lock_bh(&adapter->cloud_filter_list_lock);
 	list_for_each_entry_safe(cf, cftmp, &adapter->cloud_filter_list, list) {
 		list_del(&cf->list);
 		kfree(cf);
 		adapter->num_cloud_filters--;
 	}
 	spin_unlock_bh(&adapter->cloud_filter_list_lock);

 	iavf_free_misc_irq(adapter);
 	iavf_free_interrupt_scheme(adapter);
 	memset(adapter->vf_res, 0, IAVF_VIRTCHNL_VF_RESOURCE_SIZE);
 	iavf_shutdown_adminq(&adapter->hw);
 	adapter->flags &= ~IAVF_FLAG_RESET_PENDING;
 	iavf_change_state(adapter, __IAVF_DOWN);
 	wake_up(&adapter->down_waitqueue);
 	dev_info(&adapter->pdev->dev, "Reset task did not complete, VF disabled\n");
 }

  **/
 static void iavf_reset_task(struct work_struct *work)
 {
 	struct iavf_adapter *adapter = container_of(work,
 						      struct iavf_adapter,
 						      reset_task);
 	struct virtchnl_vf_resource *vfres = adapter->vf_res;
 	struct net_device *netdev = adapter->netdev;
 	struct iavf_hw *hw = &adapter->hw;
 	struct iavf_mac_filter *f, *ftmp;
 	struct iavf_cloud_filter *cf;
 	enum iavf_status status;
 	u32 reg_val;
 	int i = 0, err;
 	bool running;

 	netdev_lock(netdev);

 	iavf_misc_irq_disable(adapter);
 	if (adapter->flags & IAVF_FLAG_RESET_NEEDED) {
 		adapter->flags &= ~IAVF_FLAG_RESET_NEEDED;
 		/* Restart the AQ here. If we have been reset but didn't
 		 * detect it, or if the PF had to reinit, our AQ will be hosed.
 		 */
 		iavf_shutdown_adminq(hw);
 		iavf_init_adminq(hw);
 		iavf_request_reset(adapter);
 	}
 	adapter->flags |= IAVF_FLAG_RESET_PENDING;

 	/* poll until we see the reset actually happen */
 	for (i = 0; i < IAVF_RESET_WAIT_DETECTED_COUNT; i++) {
 		reg_val = rd32(hw, IAVF_VF_ARQLEN1) &
 			  IAVF_VF_ARQLEN1_ARQENABLE_MASK;
 		if (!reg_val)
 			break;
 		usleep_range(5000, 10000);
 	}
 	if (i == IAVF_RESET_WAIT_DETECTED_COUNT) {
 		dev_info(&adapter->pdev->dev, "Never saw reset\n");
 		goto continue_reset; /* act like the reset happened */
 	}

 	/* wait until the reset is complete and the PF is responding to us */
 	for (i = 0; i < IAVF_RESET_WAIT_COMPLETE_COUNT; i++) {
 		/* sleep first to make sure a minimum wait time is met */
 		msleep(IAVF_RESET_WAIT_MS);

 		reg_val = rd32(hw, IAVF_VFGEN_RSTAT) &
 			  IAVF_VFGEN_RSTAT_VFR_STATE_MASK;
 		if (reg_val == VIRTCHNL_VFR_VFACTIVE)
 			break;
 	}

 	pci_set_master(adapter->pdev);
 	pci_restore_msi_state(adapter->pdev);

 	if (i == IAVF_RESET_WAIT_COMPLETE_COUNT) {
 		dev_err(&adapter->pdev->dev, "Reset never finished (%x)\n",
 			reg_val);
 		iavf_disable_vf(adapter);
 		netdev_unlock(netdev);
 		return; /* Do not attempt to reinit. It's dead, Jim. */
 	}

 continue_reset:
 	/* If we are still early in the state machine, just restart. */
 	if (adapter->state <= __IAVF_INIT_FAILED) {
 		iavf_shutdown_adminq(hw);
 		iavf_change_state(adapter, __IAVF_STARTUP);
 		iavf_startup(adapter);
 		queue_delayed_work(adapter->wq, &adapter->watchdog_task,
 				   msecs_to_jiffies(30));
 		netdev_unlock(netdev);
 		return;
 	}

 	/* We don't use netif_running() because it may be true prior to
 	 * ndo_open() returning, so we can't assume it means all our open
 	 * tasks have finished, since we're not holding the rtnl_lock here.
 	 */
 	running = adapter->state == __IAVF_RUNNING;

 	if (running) {
 		netif_carrier_off(netdev);
 		netif_tx_stop_all_queues(netdev);
 		adapter->link_up = false;
 		iavf_napi_disable_all(adapter);
 	}
 	iavf_irq_disable(adapter);

 	iavf_change_state(adapter, __IAVF_RESETTING);
 	adapter->flags &= ~IAVF_FLAG_RESET_PENDING;

+	iavf_ptp_release(adapter);
+
 	/* free the Tx/Rx rings and descriptors, might be better to just
 	 * re-use them sometime in the future
 	 */
 	iavf_free_all_rx_resources(adapter);
 	iavf_free_all_tx_resources(adapter);

 	adapter->flags |= IAVF_FLAG_QUEUES_DISABLED;
 	/* kill and reinit the admin queue */
 	iavf_shutdown_adminq(hw);
 	adapter->current_op = VIRTCHNL_OP_UNKNOWN;
 	status = iavf_init_adminq(hw);
 	if (status) {
 		dev_info(&adapter->pdev->dev, "Failed to init adminq: %d\n",
 			 status);
 		goto reset_err;
 	}
 	adapter->aq_required = 0;

 	if ((adapter->flags & IAVF_FLAG_REINIT_MSIX_NEEDED) ||
 	    (adapter->flags & IAVF_FLAG_REINIT_ITR_NEEDED)) {
 		err = iavf_reinit_interrupt_scheme(adapter, running);
 		if (err)
 			goto reset_err;
 	}

 	if (RSS_AQ(adapter)) {
 		adapter->aq_required |= IAVF_FLAG_AQ_CONFIGURE_RSS;
 	} else {
 		err = iavf_init_rss(adapter);
 		if (err)
 			goto reset_err;
 	}

 	adapter->aq_required |= IAVF_FLAG_AQ_GET_CONFIG;
 	adapter->aq_required |= IAVF_FLAG_AQ_MAP_VECTORS;

 	/* Certain capabilities require an extended negotiation process using
 	 * extra messages that must be processed after getting the VF
 	 * configuration. The related checks such as VLAN_V2_ALLOWED() are not
 	 * reliable here, since the configuration has not yet been negotiated.
 	 *
 	 * Always set these flags, since them related VIRTCHNL messages won't
 	 * be sent until after VIRTCHNL_OP_GET_VF_RESOURCES.
 	 */
 	adapter->aq_required |= IAVF_FLAG_AQ_EXTENDED_CAPS;

 	spin_lock_bh(&adapter->mac_vlan_list_lock);

 	/* Delete filter for the current MAC address, it could have
 	 * been changed by the PF via administratively set MAC.
 	 * Will be re-added via VIRTCHNL_OP_GET_VF_RESOURCES.
 	 */
 	list_for_each_entry_safe(f, ftmp, &adapter->mac_filter_list, list) {
 		if (ether_addr_equal(f->macaddr, adapter->hw.mac.addr)) {
 			list_del(&f->list);
 			kfree(f);
 		}
 	}
 	/* re-add all MAC filters */
 	list_for_each_entry(f, &adapter->mac_filter_list, list) {
 		f->add = true;
 	}
 	spin_unlock_bh(&adapter->mac_vlan_list_lock);

 	/* check if TCs are running and re-add all cloud filters */
 	spin_lock_bh(&adapter->cloud_filter_list_lock);
 	if ((vfres->vf_cap_flags & VIRTCHNL_VF_OFFLOAD_ADQ) &&
 	    adapter->num_tc) {
 		list_for_each_entry(cf, &adapter->cloud_filter_list, list) {
 			cf->add = true;
 		}
 	}
 	spin_unlock_bh(&adapter->cloud_filter_list_lock);

 	adapter->aq_required |= IAVF_FLAG_AQ_ADD_MAC_FILTER;
 	adapter->aq_required |= IAVF_FLAG_AQ_ADD_CLOUD_FILTER;
 	iavf_misc_irq_enable(adapter);

 	mod_delayed_work(adapter->wq, &adapter->watchdog_task, 2);

 	/* We were running when the reset started, so we need to restore some
 	 * state here.
 	 */
 	if (running) {
 		/* allocate transmit descriptors */
 		err = iavf_setup_all_tx_resources(adapter);
 		if (err)
 			goto reset_err;

 		/* allocate receive descriptors */
 		err = iavf_setup_all_rx_resources(adapter);
 		if (err)
 			goto reset_err;

 		if ((adapter->flags & IAVF_FLAG_REINIT_MSIX_NEEDED) ||
 		    (adapter->flags & IAVF_FLAG_REINIT_ITR_NEEDED)) {
 			err = iavf_request_traffic_irqs(adapter, netdev->name);
 			if (err)
 				goto reset_err;

 			adapter->flags &= ~IAVF_FLAG_REINIT_MSIX_NEEDED;
 		}

 		iavf_configure(adapter);

 		/* iavf_up_complete() will switch device back
 		 * to __IAVF_RUNNING
 		 */
 		iavf_up_complete(adapter);

 		iavf_irq_enable(adapter, true);

 		iavf_reconfig_qs_bw(adapter);
 	} else {
 		iavf_change_state(adapter, __IAVF_DOWN);
 		wake_up(&adapter->down_waitqueue);
 	}

 	adapter->flags &= ~IAVF_FLAG_REINIT_ITR_NEEDED;

 	wake_up(&adapter->reset_waitqueue);
 	netdev_unlock(netdev);

 	return;
 reset_err:
 	if (running) {
 		set_bit(__IAVF_VSI_DOWN, adapter->vsi.state);
 		iavf_free_traffic_irqs(adapter);
 	}
 	iavf_disable_vf(adapter);

 	netdev_unlock(netdev);
 	dev_err(&adapter->pdev->dev, "failed to allocate resources during reinit\n");
 }



